{"code":"import numpy as np, wave, json
from pathlib import Path
from scipy import signal
def name(m):
 return ['C','C#','D','Eb','E','F','F#','G','Ab','A','Bb','B'][int(m)%12]+str(int(m)//12-1)
def calc(w,a,b):
 with wave.open('../candidate/input/'+w+'/performance.wav','rb') as f:
  sr=f.getframerate();f.setpos(round(a*sr));x=np.frombuffer(f.readframes(round((b-a)*sr)),dtype='<i2').reshape(-1,2).mean(axis=1)/32768
 freqs,t,z=signal.stft(x,sr,nperseg=8192,noverlap=8192-441);v=np.abs(z);t+=a
 mids=np.arange(33,97);D=np.zeros((len(freqs),len(mids)))
 for j,m in enumerate(mids):
  f0=440*2**((m-69)/12)
  for h in range(1,min(15,int(7000/f0))+1):
   f=f0*h*(1+.00004*h*h)**.5
   D[:,j]+=np.exp(-.5*((freqs-f)/max(sr/8192*.65,f*.0018))**2)/(h**.75)
 wt=1/np.maximum(np.mean(v,axis=1),np.max(v)*.001)**.55;wt[freqs<45]=0;wt[freqs>7000]=0
 d=D*wt[:,None];y=v*wt[:,None];d/=np.maximum(np.linalg.norm(d,axis=0),1e-12)
 xy=d.T@y;gram=d.T@d;H=np.maximum(xy,1e-9)
 for it in range(45):H*=np.maximum(xy-.015*np.max(xy),1e-10)/(gram@H+1e-10)
 flux=np.sum(np.maximum(v[:,1:]-v[:,:-1],0),axis=0);peaks,_=signal.find_peaks(flux,distance=9,prominence=np.max(flux)*.018)
 out={'a':a,'b':b,'t':np.round(t,3).tolist(),'m':mids.tolist(),'H':np.round(H,5).tolist(),'onsets':np.round(t[1:][peaks],3).tolist(),'flux':np.round(flux[peaks],5).tolist()}
 Path('analysis').mkdir(exist_ok=True);Path('analysis/'+w+'_'+str(a)+'.json').write_text(json.dumps(out))
 for tt in t[1:][peaks]:
  ix=(t>=tt+.015)&(t<tt+.11);pr=(t>=tt-.12)&(t<tt-.025);h=H[:,ix].mean(axis=1);hp=H[:,pr].mean(axis=1) if pr.any() else h*0;at=np.maximum(h-hp*.7,0);inds=np.argsort(at)[-4:][::-1]
  print(round(float(tt),3),' '.join(name(mids[i])+':'+str(round(float(at[i]),2)) for i in inds))
calc('A',5.7,12.8)
print('Q5');calc('A',116,127)
print('Q6');calc('A',214,226)"}

