from pathlib import Path
def nm(m):return ['C','C#','D','Eb','E','F','F#','G','Ab','A','Bb','B'][m%12]+str(m//12-1)
for w,a,b,lo,hi in [('A',171,198,60,85),('A',217,223,55,78),('A',117,127,48,67),('B',173,179,60,88),('B',270,289,60,90)]:
 d=json.loads(Path('analysis/'+w+'_all.json').read_text());t=np.array(d['t']);H=np.array(d['H']);print('\n',w,a,b)
 for tt,fl in zip(d['onsets'],d['flux']):
  if a<tt<b:
   h=H[(t>=tt)&(t<tt+.1)].mean(axis=0);pr=H[(t>=tt-.14)&(t<tt-.04)].mean(axis=0);v=np.maximum(h-.8*pr,0);v[:lo-21]=0;v[hi-20:]=0;ids=np.argsort(v)[-3:][::-1]
   if v[ids[0]]>.0015:print(tt,round(fl,3),' '.join(nm(int(i)+21)+':'+str(round(v[i],3)) for i in ids))

